use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl MmapOptions { # [doc = " Creates a new set of options for configuring and creating a memory map."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use memmap2::{MmapMut, MmapOptions};"] # [doc = " # use std::io::Result;"] # [doc = ""] # [doc = " # fn main() -> Result<()> {"] # [doc = " // Create a new memory map builder."] # [doc = " let mut mmap_options = MmapOptions::new();"] # [doc = ""] # [doc = " // Configure the memory map builder using option setters, then create"] # [doc = " // a memory map using one of `mmap_options.map_anon`, `mmap_options.map`,"] # [doc = " // `mmap_options.map_mut`, `mmap_options.map_exec`, or `mmap_options.map_copy`:"] # [doc = " let mut mmap: MmapMut = mmap_options.len(36).map_anon()?;"] # [doc = ""] # [doc = " // Use the memory map:"] # [doc = " mmap.copy_from_slice(b\"...data to copy to the memory map...\");"] # [doc = " # Ok(())"] # [doc = " # }"] # [doc = " ```"] pub fn new () -> MmapOptions { MmapOptions :: default () } # [doc = " Configures the memory map to start at byte `offset` from the beginning of the file."] # [doc = ""] # [doc = " This option has no effect on anonymous memory maps."] # [doc = ""] # [doc = " By default, the offset is 0."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use memmap2::MmapOptions;"] # [doc = " use std::fs::File;"] # [doc = ""] # [doc = " # fn main() -> std::io::Result<()> {"] # [doc = " let mmap = unsafe {"] # [doc = "     MmapOptions::new()"] # [doc = "                 .offset(30)"] # [doc = "                 .map(&File::open(\"LICENSE-APACHE\")?)?"] # [doc = " };"] # [doc = " assert_eq!(&b\"Apache License\"[..],"] # [doc = "            &mmap[..14]);"] # [doc = " # Ok(())"] # [doc = " # }"] # [doc = " ```"] pub fn offset (& mut self , offset : u64) -> & mut Self { self . offset = offset ; self } # [doc = " Configures the created memory mapped buffer to be `len` bytes long."] # [doc = ""] # [doc = " This option is mandatory for anonymous memory maps."] # [doc = ""] # [doc = " For file-backed memory maps, the length will default to the file length."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use memmap2::MmapOptions;"] # [doc = " use std::fs::File;"] # [doc = ""] # [doc = " # fn main() -> std::io::Result<()> {"] # [doc = " let mmap = unsafe {"] # [doc = "     MmapOptions::new()"] # [doc = "                 .len(9)"] # [doc = "                 .map(&File::open(\"README.md\")?)?"] # [doc = " };"] # [doc = " assert_eq!(&b\"# memmap2\"[..], &mmap[..]);"] # [doc = " # Ok(())"] # [doc = " # }"] # [doc = " ```"] pub fn len (& mut self , len : usize) -> & mut Self { self . len = Some (len) ; self } fn validate_len (len : u64) -> Result < usize > { if isize :: try_from (len) . is_err () { return Err (Error :: new (ErrorKind :: InvalidData , "memory map length overflows isize" ,)) ; } Ok (len as usize) } # [doc = " Returns the configured length, or the length of the provided file."] fn get_len < T : MmapAsRawDesc > (& self , file : & T) -> Result < usize > { let len = if let Some (len) = self . len { len as u64 } else { let desc = file . as_raw_desc () ; let file_len = file_len (desc . 0) ? ; if file_len < self . offset { return Err (Error :: new (ErrorKind :: InvalidData , "memory map offset is larger than length" ,)) ; } file_len - self . offset } ; Self :: validate_len (len) } # [doc = " Configures the anonymous memory map to be suitable for a process or thread stack."] # [doc = ""] # [doc = " This option corresponds to the `MAP_STACK` flag on Linux. It has no effect on Windows."] # [doc = ""] # [doc = " This option has no effect on file-backed memory maps."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use memmap2::MmapOptions;"] # [doc = ""] # [doc = " # fn main() -> std::io::Result<()> {"] # [doc = " let stack = MmapOptions::new().stack().len(4096).map_anon();"] # [doc = " # Ok(())"] # [doc = " # }"] # [doc = " ```"] pub fn stack (& mut self) -> & mut Self { self . stack = true ; self } # [doc = " Configures the anonymous memory map to be allocated using huge pages."] # [doc = ""] # [doc = " This option corresponds to the `MAP_HUGETLB` flag on Linux. It has no effect on Windows."] # [doc = ""] # [doc = " The size of the requested page can be specified in page bits. If not provided, the system"] # [doc = " default is requested. The requested length should be a multiple of this, or the mapping"] # [doc = " will fail."] # [doc = ""] # [doc = " This option has no effect on file-backed memory maps."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use memmap2::MmapOptions;"] # [doc = ""] # [doc = " # fn main() -> std::io::Result<()> {"] # [doc = " let stack = MmapOptions::new().huge(Some(21)).len(2*1024*1024).map_anon();"] # [doc = " # Ok(())"] # [doc = " # }"] # [doc = " ```"] # [doc = ""] # [doc = " The number 21 corresponds to `MAP_HUGE_2MB`. See mmap(2) for more details."] pub fn huge (& mut self , page_bits : Option < u8 >) -> & mut Self { self . huge = Some (page_bits . unwrap_or (0)) ; self } # [doc = " Populate (prefault) page tables for a mapping."] # [doc = ""] # [doc = " For a file mapping, this causes read-ahead on the file. This will help to reduce blocking on page faults later."] # [doc = ""] # [doc = " This option corresponds to the `MAP_POPULATE` flag on Linux. It has no effect on Windows."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use memmap2::MmapOptions;"] # [doc = " use std::fs::File;"] # [doc = ""] # [doc = " # fn main() -> std::io::Result<()> {"] # [doc = " let file = File::open(\"LICENSE-MIT\")?;"] # [doc = ""] # [doc = " let mmap = unsafe {"] # [doc = "     MmapOptions::new().populate().map(&file)?"] # [doc = " };"] # [doc = ""] # [doc = " assert_eq!(&b\"Copyright\"[..], &mmap[..9]);"] # [doc = " # Ok(())"] # [doc = " # }"] # [doc = " ```"] pub fn populate (& mut self) -> & mut Self { self . populate = true ; self } # [doc = " Do not reserve swap space for the memory map."] # [doc = ""] # [doc = " By default, platforms may reserve swap space for memory maps."] # [doc = " This guarantees that a write to the mapped memory will succeed, even if physical memory is exhausted."] # [doc = " Otherwise, the write to memory could fail (on Linux with a segfault)."] # [doc = ""] # [doc = " This option requests that no swap space will be allocated for the memory map,"] # [doc = " which can be useful for extremely large maps that are only written to sparsely."] # [doc = ""] # [doc = " This option is currently supported on Linux, Android, Apple platforms (macOS, iOS, visionOS, etc.), NetBSD, Solaris and Illumos."] # [doc = " On those platforms, this option corresponds to the `MAP_NORESERVE` flag."] # [doc = " On Linux, this option is ignored if [`vm.overcommit_memory`](https://www.kernel.org/doc/Documentation/vm/overcommit-accounting) is set to 2."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use memmap2::MmapOptions;"] # [doc = " use std::fs::File;"] # [doc = ""] # [doc = " # fn main() -> std::io::Result<()> {"] # [doc = " let file = File::open(\"LICENSE-MIT\")?;"] # [doc = ""] # [doc = " let mmap = unsafe {"] # [doc = "     MmapOptions::new().no_reserve_swap().map_copy(&file)?"] # [doc = " };"] # [doc = ""] # [doc = " assert_eq!(&b\"Copyright\"[..], &mmap[..9]);"] # [doc = " # Ok(())"] # [doc = " # }"] # [doc = " ```"] pub fn no_reserve_swap (& mut self) -> & mut Self { self . no_reserve_swap = true ; self } # [doc = " Creates a read-only memory map backed by a file."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " See the [type-level][MmapOptions] docs for why this function is unsafe."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " This method returns an error when the underlying system call fails, which can happen for a"] # [doc = " variety of reasons, such as when the file is not open with read permissions."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use memmap2::MmapOptions;"] # [doc = " use std::fs::File;"] # [doc = " use std::io::Read;"] # [doc = ""] # [doc = " # fn main() -> std::io::Result<()> {"] # [doc = " let mut file = File::open(\"LICENSE-APACHE\")?;"] # [doc = ""] # [doc = " let mut contents = Vec::new();"] # [doc = " file.read_to_end(&mut contents)?;"] # [doc = ""] # [doc = " let mmap = unsafe {"] # [doc = "     MmapOptions::new().map(&file)?"] # [doc = " };"] # [doc = ""] # [doc = " assert_eq!(&contents[..], &mmap[..]);"] # [doc = " # Ok(())"] # [doc = " # }"] # [doc = " ```"] pub unsafe fn map < T : MmapAsRawDesc > (& self , file : T) -> Result < Mmap > { let desc = file . as_raw_desc () ; MmapInner :: map (self . get_len (& file) ? , desc . 0 , self . offset , self . populate , self . no_reserve_swap ,) . map (| inner | Mmap { inner }) } # [doc = " Creates a readable and executable memory map backed by a file."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " See the [type-level][MmapOptions] docs for why this function is unsafe."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " This method returns an error when the underlying system call fails, which can happen for a"] # [doc = " variety of reasons, such as when the file is not open with read permissions."] pub unsafe fn map_exec < T : MmapAsRawDesc > (& self , file : T) -> Result < Mmap > { let desc = file . as_raw_desc () ; MmapInner :: map_exec (self . get_len (& file) ? , desc . 0 , self . offset , self . populate , self . no_reserve_swap ,) . map (| inner | Mmap { inner }) } # [doc = " Creates a writeable memory map backed by a file."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " See the [type-level][MmapOptions] docs for why this function is unsafe."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " This method returns an error when the underlying system call fails, which can happen for a"] # [doc = " variety of reasons, such as when the file is not open with read and write permissions."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use std::fs::OpenOptions;"] # [doc = " use std::path::PathBuf;"] # [doc = ""] # [doc = " use memmap2::MmapOptions;"] # [doc = " #"] # [doc = " # fn main() -> std::io::Result<()> {"] # [doc = " # let tempdir = tempfile::tempdir()?;"] # [doc = " let path: PathBuf = /* path to file */"] # [doc = " #   tempdir.path().join(\"map_mut\");"] # [doc = " let file = OpenOptions::new().read(true).write(true).create(true).truncate(true).open(&path)?;"] # [doc = " file.set_len(13)?;"] # [doc = ""] # [doc = " let mut mmap = unsafe {"] # [doc = "     MmapOptions::new().map_mut(&file)?"] # [doc = " };"] # [doc = ""] # [doc = " mmap.copy_from_slice(b\"Hello, world!\");"] # [doc = " # Ok(())"] # [doc = " # }"] # [doc = " ```"] pub unsafe fn map_mut < T : MmapAsRawDesc > (& self , file : T) -> Result < MmapMut > { let desc = file . as_raw_desc () ; MmapInner :: map_mut (self . get_len (& file) ? , desc . 0 , self . offset , self . populate , self . no_reserve_swap ,) . map (| inner | MmapMut { inner }) } # [doc = " Creates a copy-on-write memory map backed by a file."] # [doc = ""] # [doc = " Data written to the memory map will not be visible by other processes,"] # [doc = " and will not be carried through to the underlying file."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " See the [type-level][MmapOptions] docs for why this function is unsafe."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " This method returns an error when the underlying system call fails, which can happen for a"] # [doc = " variety of reasons, such as when the file is not open with writable permissions."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use memmap2::MmapOptions;"] # [doc = " use std::fs::File;"] # [doc = " use std::io::Write;"] # [doc = ""] # [doc = " # fn main() -> std::io::Result<()> {"] # [doc = " let file = File::open(\"LICENSE-APACHE\")?;"] # [doc = " let mut mmap = unsafe { MmapOptions::new().map_copy(&file)? };"] # [doc = " (&mut mmap[..]).write_all(b\"Hello, world!\")?;"] # [doc = " # Ok(())"] # [doc = " # }"] # [doc = " ```"] pub unsafe fn map_copy < T : MmapAsRawDesc > (& self , file : T) -> Result < MmapMut > { let desc = file . as_raw_desc () ; MmapInner :: map_copy (self . get_len (& file) ? , desc . 0 , self . offset , self . populate , self . no_reserve_swap ,) . map (| inner | MmapMut { inner }) } # [doc = " Creates a copy-on-write read-only memory map backed by a file."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " See the [type-level][MmapOptions] docs for why this function is unsafe."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " This method returns an error when the underlying system call fails, which can happen for a"] # [doc = " variety of reasons, such as when the file is not open with read permissions."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use memmap2::MmapOptions;"] # [doc = " use std::fs::File;"] # [doc = " use std::io::Read;"] # [doc = ""] # [doc = " # fn main() -> std::io::Result<()> {"] # [doc = " let mut file = File::open(\"README.md\")?;"] # [doc = ""] # [doc = " let mut contents = Vec::new();"] # [doc = " file.read_to_end(&mut contents)?;"] # [doc = ""] # [doc = " let mmap = unsafe {"] # [doc = "     MmapOptions::new().map_copy_read_only(&file)?"] # [doc = " };"] # [doc = ""] # [doc = " assert_eq!(&contents[..], &mmap[..]);"] # [doc = " # Ok(())"] # [doc = " # }"] # [doc = " ```"] pub unsafe fn map_copy_read_only < T : MmapAsRawDesc > (& self , file : T) -> Result < Mmap > { let desc = file . as_raw_desc () ; MmapInner :: map_copy_read_only (self . get_len (& file) ? , desc . 0 , self . offset , self . populate , self . no_reserve_swap ,) . map (| inner | Mmap { inner }) } # [doc = " Creates an anonymous memory map."] # [doc = ""] # [doc = " The memory map length should be configured using [`MmapOptions::len()`]"] # [doc = " before creating an anonymous memory map, otherwise a zero-length mapping"] # [doc = " will be crated."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " This method returns an error when the underlying system call fails or"] # [doc = " when `len > isize::MAX`."] pub fn map_anon (& self) -> Result < MmapMut > { let len = self . len . unwrap_or (0) ; let len = Self :: validate_len (len as u64) ? ; MmapInner :: map_anon (len , self . stack , self . populate , self . huge , self . no_reserve_swap ,) . map (| inner | MmapMut { inner }) } # [doc = " Creates a raw memory map."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " This method returns an error when the underlying system call fails, which can happen for a"] # [doc = " variety of reasons, such as when the file is not open with read and write permissions."] pub fn map_raw < T : MmapAsRawDesc > (& self , file : T) -> Result < MmapRaw > { let desc = file . as_raw_desc () ; MmapInner :: map_mut (self . get_len (& file) ? , desc . 0 , self . offset , self . populate , self . no_reserve_swap ,) . map (| inner | MmapRaw { inner }) } # [doc = " Creates a read-only raw memory map"] # [doc = ""] # [doc = " This is primarily useful to avoid intermediate `Mmap` instances when"] # [doc = " read-only access to files modified elsewhere are required."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " This method returns an error when the underlying system call fails"] pub fn map_raw_read_only < T : MmapAsRawDesc > (& self , file : T) -> Result < MmapRaw > { let desc = file . as_raw_desc () ; MmapInner :: map (self . get_len (& file) ? , desc . 0 , self . offset , self . populate , self . no_reserve_swap ,) . map (| inner | MmapRaw { inner }) } }